async function refreshDigiSparkXVideos(){
  const holders=[...document.querySelectorAll('.youtube-track,.youtube-grid')];
  if(!holders.length)return;
  try{
    const res=await fetch('/api/youtube.php',{cache:'no-store'});
    const data=await res.json();
    if(!data.videos||!data.videos.length)return;
    const cards=data.videos.map(v=>`<a class="youtube-card" href="${v.url}" target="_blank" rel="noreferrer"><span class="youtube-thumb"><img loading="lazy" src="${v.thumbnail}" alt="${v.title.replace(/"/g,'&quot;')}"><span>&#9654;</span></span><small>${v.category||'DigiSparkX'}</small><h3>${v.title}</h3><p>${v.description||'Watch the latest DigiSparkX learning video.'}</p></a>`).join('');
    holders.forEach(h=>{h.innerHTML=h.classList.contains('youtube-track')?cards+cards:cards});
  }catch(e){}
}
refreshDigiSparkXVideos();
</script></body></html>